+            if (entry.misplaced) {
+                details.add("misplaced");
+            }
+            if (entry.colliding) {
+                details.add("colliding");
+            }
+            if (entry.occupied) {
+                details.add("occupied");
+            }
+            if (!details.isEmpty()) {
+                result.append(" (").append(String.join(", ", details)).append(")");
+            }
+        }
+    }
