            return delegate.contains(rule);
        }

        @Override
        public void save(ArchRule rule, List<String> violations) {
            delegate.save(rule, violations);
        }

        @Override
        public List<String> getViolations(ArchRule rule) {
            return delegate.getViolations(rule);
        }
    }
